#!/usr/bin/env bash
# СУДИТ: scripts/setup-call-guard.py
# (предмет словами: hooks/tests/*.sh (подготовительные вызовы свидетелей) через scripts/setup-call-guard.py; в строке СУДИТ — только пути, иначе прибор свидетелей-атак читает слова путями — D1222)
# probe_D1194 — в свидетелях нет подготовительного вызова, чей отказ нем: ни код не читается, ни отказ не назван (корень
# D465). Закрытие D465 стояло на разовом `--fix`, и за месяц носителей снова стало 80; проба судит дерево целиком, нога T6
# `hooks/tests/test_setup_call_guard.sh` зовёт её в каждом прогоне набора.
# Код: 0 — носителей нет; 1 — есть (названы); 2 — прибора нет или он не ответил.
R="${CLAUDSOUL_REPO:-$(cd "$(dirname "$0")/../../.." && pwd)}"
T="$R/scripts/setup-call-guard.py"
[ -f "$T" ] && command -v python3 >/dev/null 2>&1 || exit 2
n=$(cd "$R" && python3 "$T" --count < /dev/null 2>/dev/null)
case "$n" in ''|*[!0-9]*) echo "прибор не ответил числом: [${n}]"; exit 2 ;; esac
[ "$n" -eq 0 ] && { echo "немых подготовительных вызовов в свидетелях нет"; exit 0; }
(cd "$R" && python3 "$T" < /dev/null 2>/dev/null) | head -20
echo "носителей: ${n} — страж: || { echo \"подготовка мира не удалась: <файл>:<строка>\" >&2; exit 1; } либо чтение кода"
exit 1
